import { randomUUID } from "node:crypto";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, relative, resolve } from "node:path";
import { openStore, type Store } from "@godseye/store";
import { expect, it } from "vitest";
import { InfrastructureEngine } from "../packages/core/src/infrastructure.js";
import { infrastructureFixture } from "./infra-helpers.js";

async function removeFixtureDirectory(directory: string) {
  const target = resolve(directory),
    parent = resolve(tmpdir());
  const contained = relative(parent, target);
  if (
    !contained.startsWith("godseye-infrastructure-restart-") ||
    contained.includes("..") ||
    contained.includes("\\") ||
    contained.includes("/")
  )
    throw new Error("Refusing to remove an unexpected fixture directory");
  await rm(target, { recursive: true, force: true });
}

it("T-AC-23 T31 reopens durable provision intentions and reconciles without resubmitting provider mutations", async () => {
  const directory = await mkdtemp(join(tmpdir(), "godseye-infrastructure-restart-"));
  const persistent = await infrastructureFixture({ dataDir: join(directory, "control") });
  let reopened: Store | undefined;
  let closed = false;
  try {
    persistent.provider.failedAcknowledgments.add("network");
    const { allocation } = await persistent.admit();
    if (!allocation.runId) throw new Error("Fixture run missing");
    await persistent.infrastructure.foundation.tick("before-restart-worker");
    const effects = structuredClone(persistent.provider.effects);
    await persistent.store.close();
    closed = true;
    reopened = await openStore({ dataDir: join(directory, "control") });
    const restarted = new InfrastructureEngine(reopened, persistent.configuration);

    expect((await restarted.overview(persistent.freshOwner())).allocations).toMatchObject([
      { id: allocation.id, state: "unknown" },
    ]);
    expect(await restarted.foundation.tick("after-restart-worker")).toBe(false);
    await restarted.foundation.reconcile(persistent.freshOwner(), allocation.runId, randomUUID());
    expect((await restarted.overview(persistent.freshOwner())).allocations).toMatchObject([
      { id: allocation.id, state: "quarantined" },
    ]);
    expect(persistent.provider.effects).toEqual(effects);

    persistent.provider.resources.delete(allocation.id);
    await restarted.foundation.reconcile(persistent.freshOwner(), allocation.runId, randomUUID());

    expect((await restarted.overview(persistent.freshOwner())).allocations).toMatchObject([
      { id: allocation.id, state: "unknown" },
    ]);
    expect(persistent.provider.effects).toEqual(effects);
  } finally {
    await reopened?.close();
    if (!closed) await persistent.store.close();
    await removeFixtureDirectory(directory);
  }
}, 20_000);
